import fitz

input_path = "./1.pdf"
output_path = "./output.pdf"

replacements = [
    ("6100 Kiskunfélegyháza , Szőlő u 10/3/a", "7800 Siklós Perényi köz 3/2"),
    ("Kiskunfélegyháza szolo utca 10", "7800 Siklós Perényi köz 3/2"),
    ("Kiskunfélegyháza Szőlő utca 10", "7800 Siklós Perényi köz 3/2"),
    ("KOLLÁR Sándor", "DUKITS Zoltán"),
    ("Kollár Sándor", "Dukits Zoltán"),
    ("Kollár", "Dukits"),
    ("Sándor", "Zoltán"),
    ("Szabó Katalin", "Kővári Judit"),
    ("Szabó Katalint", "Kővári Judit"),
    ("2003.04.16 Kiskunfélegyházat", "2001.01.30 Siklósra"),
    ("2003.04.16. Kiskunfélegyháza", "2001.01.30. Siklós"),
    ("2003.04.16 Kiskunfélegyháza", "2001.01.30 Siklós"),
    ("2003.04.16.", "2001.01.30."),
    ("2003.04.16", "2001.01.30"),
    ("KOLLÁR", "DUKITS"),
    ("Kiskunfélegyháza", "Siklós"),
]

fitz.TOOLS.set_subset_fontnames(True)


def int_to_rgb(color_int):
    if isinstance(color_int, (tuple, list)):
        return tuple(color_int)
    r = ((color_int >> 16) & 255) / 255
    g = ((color_int >> 8) & 255) / 255
    b = (color_int & 255) / 255
    return (r, g, b)


def get_span_style(page, rect):
    text_dict = page.get_text("dict", clip=rect)
    blocks = text_dict.get("blocks", [])
    for block in blocks:
        for line in block.get("lines", []):
            for span in line.get("spans", []):
                return {
                    "font": span.get("font", "helv"),
                    "size": span.get("size", 10),
                    "color": int_to_rgb(span.get("color", 0)),
                }
    return {
        "font": "helv",
        "size": 10,
        "color": (0, 0, 0),
    }


def resolve_font_alias(page, doc, span_font_name):
    font_list = page.get_fonts()
    normalized_span = span_font_name.split("+", 1)[-1].lower()
    for xref, ext, ftype, basefont, name, encoding, referencer in font_list:
        candidates = [str(basefont), str(name)]
        for candidate in candidates:
            normalized_candidate = candidate.split("+", 1)[-1].lower()
            if normalized_candidate == normalized_span:
                try:
                    extracted = doc.extract_font(xref)
                    font_buffer = extracted[-1]
                    if font_buffer:
                        alias = f"F{xref}"
                        page.insert_font(fontname=alias, fontbuffer=font_buffer)
                        return alias
                except Exception:
                    pass
    return "helv"


document = fitz.open(input_path)

for page in document:
    matched_rects = []
    to_insert = []
    for old_text, new_text in replacements:
        text_instances = page.search_for(old_text)
        for inst in text_instances:
            overlaps = False
            for matched in matched_rects:
                if inst.intersects(matched):
                    overlaps = True
                    break
            if not overlaps:
                style = get_span_style(page, inst)
                fontname = resolve_font_alias(page, document, style["font"])
                page.add_redact_annot(inst, fill=(1, 1, 1))
                matched_rects.append(inst)
                insert_point = fitz.Point(inst.x0, inst.y1 - 2)
                to_insert.append((insert_point, new_text, fontname, style["size"], style["color"]))
    page.apply_redactions()
    for point, text, fontname, fontsize, color in to_insert:
        page.insert_text(point, text, fontsize=fontsize, fontname=fontname, color=color)

document.save(output_path)
document.close()
